package com.alsafa.native4.core;
import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import org.json.JSONObject;import java.util.*;
/** Receives strictly ordered Native4 operations. Applied IDs make retries harmless; checkpoint advances only after commit. */
public final class Native4SyncReceiver{
 public interface Source{Batch fetchAfter(long revision,int limit)throws Exception;}public interface Applier{void apply(SQLiteDatabase db,RemoteOp op)throws Exception;}
 public static final class RemoteOp{public final long revision;public final String id,kind,recordId,payload,sourceDeviceId;public RemoteOp(long r,String i,String k,String rid,String p,String d){revision=r;id=i;kind=k;recordId=rid;payload=p;sourceDeviceId=d;}}
 public static final class Batch{public final List<RemoteOp> operations;public Batch(List<RemoteOp> x){if(x==null)throw new IllegalArgumentException("Remote sync batch operations must not be null");operations=Collections.unmodifiableList(new ArrayList<>(x));}}
 private static final String KEY="native4_remote_revision";private final CoreDb core;private final Source source;private final Applier applier;
 public Native4SyncReceiver(CoreDb c,Source s,Applier a){if(c==null||s==null||a==null)throw new IllegalArgumentException("Sync receiver dependencies مطلوبة");core=c;source=s;applier=a;}
 public interface Progress{void onOperation(String kind,String recordId,String payload,int index,int total);}
 public Result pullOnce()throws Exception{return pullOnce(null);}
 public Result pullOnce(Progress progress)throws Exception{core.db().execSQL("CREATE TABLE IF NOT EXISTS received_sync_log(operation_id TEXT PRIMARY KEY,operation_kind TEXT,record_id TEXT,payload TEXT,source_device_id TEXT,revision INTEGER,received_at INTEGER)");long checkpoint=checkpoint();int applied=0,duplicates=0;long last=checkpoint;for(int page=0;page<20;page++){Batch b=source.fetchAfter(last,100);if(b==null||b.operations==null||b.operations.size()>100)throw new IllegalStateException("حجم دفعة الاستقبال غير صالح؛ أُوقف الاستقبال لحماية التسلسل");List<RemoteOp> ops=new ArrayList<>(b.operations);if(ops.contains(null))throw new IllegalStateException("سجل مزامنة فارغ ضمن الدفعة");if(ops.isEmpty())return new Result(applied,duplicates,last);for(RemoteOp candidate:ops){if(candidate.revision<=0||candidate.id==null||candidate.id.trim().isEmpty()||candidate.kind==null||candidate.kind.trim().isEmpty()||candidate.recordId==null||candidate.recordId.trim().isEmpty()||candidate.payload==null||candidate.payload.trim().isEmpty()||candidate.sourceDeviceId==null||candidate.sourceDeviceId.trim().isEmpty())throw new IllegalStateException("دفعة الاستقبال تحتوي على عملية ناقصة البيانات");}ops.sort(Comparator.comparingLong(o->o.revision));Set<Long> batchRevisions=new HashSet<>();Set<String> batchIds=new HashSet<>();for(RemoteOp candidate:ops){if(!batchRevisions.add(candidate.revision)||!batchIds.add(candidate.id))throw new IllegalStateException("دفعة المزامنة تحتوي على رقم تسلسلي أو معرف مكرر؛ أُوقف الاستقبال لحماية البيانات");}long expected=last;for(RemoteOp candidate:ops){if(expected==Long.MAX_VALUE||candidate.revision!=expected+1)throw new IllegalStateException("فجوة أو تراجع في تسلسل دفعة الاستقبال؛ لم تُطبّق أي عملية من هذه الدفعة");expected=candidate.revision;try{new JSONObject(candidate.payload);}catch(org.json.JSONException invalidPayload){throw new IllegalStateException("محتوى عملية واردة ليس JSON صالحًا؛ لم تُطبّق أي عملية من هذه الدفعة",invalidPayload);}}int index=0;for(RemoteOp op:ops){index++;if(progress!=null){try{progress.onOperation(op.kind,op.recordId,op.payload,index,ops.size());}catch(RuntimeException callbackError){android.util.Log.w("Native4Sync","Receive progress callback failed; apply continues",callbackError);}}if(already(op.id)){advance(op.revision);last=op.revision;duplicates++;continue;}SQLiteDatabase db=core.db();db.beginTransaction();try{JSONObject payload=new JSONObject(op.payload);boolean handled=false;if("SALE_UPDATE".equals(op.kind)){OnlineSaleRemoteApplier.apply(db,op);handled=true;}else if(ReservationRemoteApplier.tryApply(db,op))handled=true;else if(AlsafaCareRemoteApplier.tryApply(db,op,payload))handled=true;else if("SETTING".equals(op.kind))handled=RepairPartRemoteApplier.apply(db,op.id,op.recordId,payload);if(!handled)applier.apply(db,op);ContentValues a=new ContentValues();a.put("operation_id",op.id);a.put("applied_at",System.currentTimeMillis());db.insertOrThrow("applied",null,a);writeCheckpoint(db,op.revision);ContentValues log=new ContentValues();log.put("operation_id",op.id);log.put("operation_kind",op.kind);log.put("record_id",op.recordId);log.put("payload",op.payload);log.put("source_device_id",op.sourceDeviceId);log.put("revision",op.revision);log.put("received_at",System.currentTimeMillis());db.insertOrThrow("received_sync_log",null,log);db.setTransactionSuccessful();}finally{db.endTransaction();}applied++;last=op.revision;}if(ops.size()<100)return new Result(applied,duplicates,last);}return new Result(applied,duplicates,last);}
 private boolean already(String id){try(Cursor c=core.db().rawQuery("SELECT 1 FROM applied WHERE operation_id=? LIMIT 1",new String[]{id})){return c.moveToFirst();}}
 private long checkpoint(){try(Cursor c=core.db().rawQuery("SELECT checkpoint_value FROM sync_checkpoint WHERE checkpoint_key=?",new String[]{KEY})){if(c.moveToFirst()){String saved=c.getString(0);try{long revision=Long.parseLong(saved);if(revision<0)throw new NumberFormatException("negative revision");return revision;}catch(NumberFormatException invalid){throw new IllegalStateException("مؤشر استقبال المزامنة غير صالح؛ تم إيقاف الاستقبال لحماية البيانات",invalid);}}}return 0;}
 private void advance(long revision){SQLiteDatabase db=core.db();db.beginTransaction();try{writeCheckpoint(db,revision);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 private static void writeCheckpoint(SQLiteDatabase db,long revision){ContentValues v=new ContentValues();v.put("checkpoint_key",KEY);v.put("checkpoint_value",String.valueOf(revision));v.put("updated_at",System.currentTimeMillis());db.insertWithOnConflict("sync_checkpoint",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 public static final class Result{public final int applied,duplicates;public final long checkpoint;Result(int a,int d,long c){applied=a;duplicates=d;checkpoint=c;}}
}
